package app

import (
 "context"
 "encoding/json"
 "fmt"
 "os"
 "path/filepath"
 "reflect"
 "strings"
 "testing"
 "unicode/utf8"

 "edge-api/internal/config"
 "edge-api/internal/kafka"
 qrsvc "edge-api/internal/services/auth/qr"
)

// MSGKEY-003: every published QR notice must satisfy the consumer's param limits without changing its English text.
func TestMSGKEY_003_QRRequesterParamBoundaries(t *testing.T) {
 previous:=kafka.GetCommandProducer()
 t.Cleanup(func(){kafka.SetCommandProducer(previous)})
 runtime:=config.Runtime()
 t.Cleanup(func(){config.SetRuntime(runtime)})
 env:=runtime
 env.Common.NotificationDeeplinkScheme="acme"
 config.SetRuntime(env)
 type sample struct{name,value string; field string}
 samples:=[]sample{{name:"normal",value:"Browser/1.0",field:"requester_user_agent"},{name:"null"}}
 for _,field:=range []string{"requester_ip","requester_geo_city","requester_geo_country","requester_user_agent"} {
 for _,text:=range []struct{name,unit string}{{"ascii","A"},{"multibyte","界"}} {
 for _,size:=range []int{1024,1025} {
 samples=append(samples,sample{name:fmt.Sprintf("%s_%s_%d",field,text.name,size),field:field,value:strings.Repeat(text.unit,size)})
 }
 }
 }
 for _,tc:=range samples {t.Run(tc.name,func(t *testing.T){
 producer:=&qrNotificationCaptureProducer{}
 kafka.SetCommandProducer(producer)
 input:=qrsvc.NotificationInput{QRLoginID:"qr-boundary",ApprovedAccountID:"acc-1",RequesterIP:"203.0.113.10"}
 expectedParams:=map[string]string{"requester_ip":input.RequesterIP}
 city,country,browser:="unknown","unknown","unknown"
 switch tc.field {
 case "requester_ip":input.RequesterIP=tc.value;expectedParams[tc.field]=tc.value
 case "requester_geo_city":input.RequesterGeoCity=&tc.value;expectedParams[tc.field]=tc.value;city=tc.value
 case "requester_geo_country":input.RequesterGeoCountry=&tc.value;expectedParams[tc.field]=tc.value;country=tc.value
 case "requester_user_agent":input.RequesterUserAgent=&tc.value;expectedParams[tc.field]=tc.value;browser=tc.value
 }
 if err:=(qrLoginNotificationPublisher{}).PublishQRLoginCompleted(context.Background(),input);err!=nil {t.Fatal(err)}
 // Optional synthetic wire fixtures are checked by the paired consumer decoder as well.
 if directory:=os.Getenv("EDGE_API_QR_NOTIFICATION_CONSUMER_FIXTURES");directory!="" {
 if err:=os.MkdirAll(directory,0700);err!=nil {t.Fatal(err)}
 if err:=os.WriteFile(filepath.Join(directory,tc.name+".json"),producer.value,0600);err!=nil {t.Fatal(err)}
 }
 var envelope struct {Payload struct {Send map[string]any `json:"send_command"`} `json:"payload"`}
 if err:=json.Unmarshal(producer.value,&envelope);err!=nil {t.Fatal(err)}
 send:=envelope.Payload.Send
 wantBody:="A new session was signed in to your account by QR code from "+city+", "+country+" ("+input.RequesterIP+") on "+browser+". If this was not you, sign out all sessions and secure your account."
 if send["body"]!=wantBody || send["title"]!="New sign-in approved by QR code" {t.Fatal("English text changed")}
 if producer.topic!=kafka.TopicCmdNotificationsSendV1 || !reflect.DeepEqual(send["channels"],[]any{"IN_APP","PUSH"}) {t.Fatalf("security delivery changed: %v",send["channels"])}
 if send["message_key"]==nil {
 if send["message_params"]!=nil {t.Fatal("null key requires null params")}
 if utf8.RuneCountInString(tc.value)<=1024 {t.Fatal("valid values lost the message key")}
 return
 }
 if send["message_key"]!="security.qr_login.completed" {t.Fatalf("unexpected key %v",send["message_key"])}
 var params map[string]string
 raw,err:=json.Marshal(send["message_params"]);if err!=nil {t.Fatal(err)}
 if err:=json.Unmarshal(raw,&params);err!=nil {t.Fatal(err)}
 if !reflect.DeepEqual(params,expectedParams) {t.Fatal("params no longer match English text")}
 for name,value:=range params {if utf8.RuneCountInString(value)>1024 {t.Fatalf("published %s has %d characters; consumer maximum is 1024",name,utf8.RuneCountInString(value))}}
 })}
}
EOF
