package qr

import (
 "context"
 "strings"
 "testing"

 "edge-api/internal/constants"
)

// MSGKEY-003: a challenge stored before message keys existed still completes without rewriting requester attribution.
func TestMSGKEY_003_PollAlreadyStoredLongRequester(t *testing.T) {
 fixture:=setupQRServiceTest(t)
 SetDeps(fixture.deps)
 pollSecret,rec:=fixture.approvedChallenge(t)
 value:=strings.Repeat("界",1025)
 rec.RequesterUserAgent=&value
 fixture.store.byID[rec.QRLoginID]=rec
 result,err:=ExecutePollService(context.Background(),PollInput{QRLoginID:rec.QRLoginID,PollSecret:pollSecret})
 if err!=nil {t.Fatal(err)}
 if result.Status!=constants.QR_LOGIN_STATUS_APPROVED || result.AccessToken=="" || result.RefreshToken!="refresh-token" {t.Fatalf("stored challenge did not complete: %+v",result)}
 if fixture.publisher.calls!=1 || fixture.publisher.input.RequesterUserAgent==nil || *fixture.publisher.input.RequesterUserAgent!=value || fixture.issuer.actor.UserAgent!=value {t.Fatal("stored requester attribution changed before publication or login")}
}
