class RiskLedgerError(ValueError):
    """The source image or ledger transaction cannot be represented safely."""


class RiskLedgerCapacityError(RiskLedgerError):
    """The complete atomic transaction exceeds the contract's bounds."""


class RegistryIdentityBoundsError(RiskLedgerCapacityError):
    """A Registry identity or key cannot be written without changing its bytes."""


def _byte_length(value: object) -> int:
    if isinstance(value, str):
        try:
            return len(value.encode("utf-8"))
        except UnicodeEncodeError:
            pass
    raise RegistryIdentityBoundsError("BO_REQUEST_INVALID: Registry identity must be UTF-8 text")


def check_identity(table: str, field: str, value: object) -> None:
    if not 1 <= _byte_length(value) <= _IDENTITY_MAX_BYTES:
        raise RegistryIdentityBoundsError(
            f"BO_REQUEST_INVALID: {table}.{field} must contain 1..128 UTF-8 bytes"
        )


def check_row(table: str, row: Mapping[str, object]) -> None:
    for field in IDENTITY_FIELDS.get(table, ()):
        check_identity(table, field, row.get(field))


def _text_attribute(value: object) -> object:
    return cast(Mapping[str, object], value).get("S") if isinstance(value, Mapping) else value


def check_key_sizes(transact_items: Sequence[Mapping[str, object]]) -> None:
    """Check every written control/revision/history key, including delete evidence.

    These key names also occur on adjacent Registry tables; applying the same
    DynamoDB limits there keeps custom physical table names safe. Conditions
    and physical deletes are exempt: neither inserts nor replaces the old row.
    """
    for wrapper in transact_items:
        for operation in ("Put", "Update"):
            raw = wrapper.get(operation)
            if not isinstance(raw, Mapping):
                continue
            item = cast(Mapping[str, object], raw)
            source = item.get("Item" if operation == "Put" else "Key")
            if not isinstance(source, Mapping):
                continue
            for field, value in cast(Mapping[str, object], source).items():
                limit = _KEY_LIMITS.get(field)
                if limit is not None and not 1 <= _byte_length(_text_attribute(value)) <= limit:
                    raise RegistryIdentityBoundsError(
                        f"BO_REQUEST_INVALID: Registry {field} exceeds {limit} UTF-8 bytes"
                    )


def check_transaction_identities(
    transact_items: Sequence[Mapping[str, object]],
    table_names: Mapping[str, str] | None = None,
) -> None:
    reverse = {physical: logical for logical, physical in (table_names or {}).items()}
    for wrapper in transact_items:
        for operation in ("Put", "Update"):
            raw = wrapper.get(operation)
            if not isinstance(raw, Mapping):
                continue
            item = cast(Mapping[str, object], raw)
            physical = item.get("TableName")
            if not isinstance(physical, str):
                continue
            logical = reverse.get(physical, physical.rsplit(".", 1)[-1])
            source = item.get("Item" if operation == "Put" else "Key")
            if logical in IDENTITY_FIELDS and isinstance(source, Mapping):
                row = cast(Mapping[str, object], source)
                check_row(logical, {k: _text_attribute(v) for k, v in row.items()})
