package dev.torcore.internal.embedded

import android.content.Context
import android.net.LocalSocket
import android.net.LocalSocketAddress
import android.system.Os
import android.system.OsConstants
import dev.torcore.*
import dev.torcore.spi.*
import java.io.File
import java.util.concurrent.CountDownLatch
import java.util.concurrent.ScheduledThreadPoolExecutor
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicBoolean

internal class EmbeddedFactory(context: Context) : EngineFactory {
    private val app = context.applicationContext
    override fun create(kind: ProviderKind, sink: EngineSink): Engine =
        if (kind == ProviderKind.EMBEDDED) EmbeddedEngine(app, sink) else DefaultEngines.create(kind, sink)
}

/** One instance/child per generation. CoreRuntime serializes commands; fresh queries gate readiness. */
internal class EmbeddedEngine(private val context: Context, private val sink: EngineSink) : Engine {
    private var handle = 0L
    private var control: ControlClient? = null
    private var watcher: Thread? = null
    private val exited = CountDownLatch(1)
    private val stopping = AtomicBoolean(false)
    private val failed = AtomicBoolean(false)
    private var generation = 0L
    @Volatile private var observations: EngineScope? = null
    @Volatile private var phase = BootstrapPhase.CONNECTING_TO_RELAY
    private var enabled = false
    private var poller: ScheduledThreadPoolExecutor? = null
    private val run = File(context.noBackupFilesDir, "torcore/run")
    private fun signal(kind: SignalKind, scope: EngineScope, value: Long = 0, id: Long = 0, revision: Long = 0, endpoint: SocksEndpoint? = null, error: TorErrorCode = TorErrorCode.ENGINE_EXITED) {
        sink.post(EngineSignal(kind, scope, value, id, revision, endpoint, error = error))
    }
    @Synchronized override fun submit(command: EngineCommand) {
        val scope = command.scope
        if (command.kind != CommandKind.START && scope.generation != generation) return
        if (command.kind != CommandKind.STOP && (stopping.get() || failed.get())) return
        try {
            when (command.kind) {
                CommandKind.START -> start(command)
                CommandKind.STOP -> stop(scope)
                CommandKind.SET_NETWORK_ENABLED -> {
                    if (!command.enabled) observations = null
                    controlOrFail().command("SETCONF DisableNetwork=" + if (command.enabled) "0" else "1")
                    enabled = command.enabled
                    signal(SignalKind.NETWORK_MODE_APPLIED, scope, if (enabled) 1 else 0)
                }
                CommandKind.REQUEST_READINESS -> { observations = scope; if (enabled) refresh(scope) }
                CommandKind.NEW_IDENTITY -> controlOrFail().command("SIGNAL NEWNYM")
                CommandKind.LOAD_CLIENT_AUTH, CommandKind.REMOVE_CLIENT_AUTH -> {
                    for (record in command.auth) {
                        val address = record.onion.reveal().removeSuffix(".onion")
                        if (command.kind == CommandKind.LOAD_CLIENT_AUTH) {
                            val bytes = record.key?.copyBytes() ?: throw IllegalStateException("CLIENT_AUTH_FAILED")
                            try { controlOrFail().addAuth(address, bytes) } finally { bytes.fill(0) }
                        } else controlOrFail().removeAuth(address)
                        signal(if (command.kind == CommandKind.LOAD_CLIENT_AUTH) SignalKind.CLIENT_AUTH_LOADED else SignalKind.CLIENT_AUTH_REMOVED,
                            EngineScope(generation, scope.round, command.authRevision), id = record.id, revision = record.revision)
                    }
                }
            }
        } catch (_: Exception) {
            when (command.kind) {
                CommandKind.STOP -> Unit // No cleanup acknowledgement permits a replacement; runtime's stop deadline fails closed.
                CommandKind.START -> { failed.set(true); signal(SignalKind.EXITED, scope, error = TorErrorCode.ENGINE_START_FAILED) }
                CommandKind.LOAD_CLIENT_AUTH, CommandKind.REMOVE_CLIENT_AUTH -> {
                    failed.set(true); signal(SignalKind.CLIENT_AUTH_FAILED, EngineScope(generation, scope.round, command.authRevision))
                }
                else -> controlLost()
            }
        }
    }
    private fun controlOrFail(): ControlClient = control ?: throw IllegalStateException("CONTROL_LOST")
    private fun privateDir(file: File) {
        check(file.mkdirs() || file.isDirectory) { "ENGINE_START_FAILED" }
        val info = Os.lstat(file.absolutePath)
        check(OsConstants.S_ISDIR(info.st_mode) && info.st_uid == android.os.Process.myUid()) { "ENGINE_START_FAILED" }
        Os.chmod(file.absolutePath, 448)
    }
    private fun start(command: EngineCommand) {
        check(generation == 0L) { "ENGINE_START_FAILED" }; generation = command.scope.generation
        check((command.provider as? ProviderConfig.Embedded)?.bridges === BridgeConfig.None) { "ENGINE_UNAVAILABLE" }
        val root = File(context.noBackupFilesDir, "torcore")
        val data = File(root, "tor"); val cache = File(context.cacheDir, "torcore")
        listOf(root, data, cache, run).forEach(::privateDir)
        val auth = File(run, "auth"); privateDir(auth)
        check(auth.list()?.isEmpty() == true) { "CLIENT_AUTH_FAILED" }
        for (name in listOf("socks", "control", "cookie")) {
            val file = File(run, name)
            if (file.exists()) check(file.delete()) { "ENGINE_START_FAILED" }
        }
        val executable = File(context.applicationInfo.nativeLibraryDir, "libtorcore_tor.so")
        val config = TorrcBuilder.build(data.absolutePath, cache.absolutePath, run.absolutePath, android.os.Process.myPid())
        try { handle = NativeTor.launch(executable.absolutePath, config) } finally { config.fill(0) }
        watcher = Thread({
            try { while (!NativeTor.poll(handle)) Thread.sleep(20) }
            finally { exited.countDown(); if (!stopping.get()) signal(SignalKind.EXITED, EngineScope(generation, 0)) }
        }, "torcore-child").apply { isDaemon = true; start() }
        val deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(1500)
        val cookieFile = File(run, "cookie")
        val socketFile = File(run, "control")
        while ((!socketFile.exists() || cookieFile.length() != 32L) && exited.count != 0L && System.nanoTime() < deadline) Thread.sleep(10)
        check(exited.count != 0L && cookieFile.length() == 32L) { "ENGINE_START_FAILED" }
        for (file in listOf(cookieFile, socketFile, File(run, "socks"))) {
            val stat = Os.lstat(file.absolutePath)
            check(stat.st_uid == android.os.Process.myUid() && stat.st_mode and 63 == 0) { "ENGINE_START_FAILED" }
        }
        val socket = LocalSocket()
        try {
            socket.connect(LocalSocketAddress(socketFile.absolutePath, LocalSocketAddress.Namespace.FILESYSTEM))
            val client = ControlClient(socket.inputStream, socket.outputStream, { socket.close() }, { text ->
                observations?.let { scope ->
                    ControlEvents.parse(text, scope, phase).forEach { fact ->
                        if (fact.kind == SignalKind.PROGRESS) phase = fact.phase
                        // Circuit/endpoint readiness comes exclusively from the fresh query barrier below.
                        if (fact.kind != SignalKind.CIRCUIT_ESTABLISHED) sink.post(fact)
                    }
                }
            }, ::controlLost)
            control = client
            val cookie = cookieFile.readBytes()
            try { client.authenticate(cookie) } finally { cookie.fill(0) }
            signal(SignalKind.CONTROL_AUTHENTICATED, command.scope)
        } catch (_: Exception) { socket.close(); throw IllegalStateException("CONTROL_PROTOCOL") }
        poller = ScheduledThreadPoolExecutor(1) { task -> Thread(task, "torcore-readiness").apply { isDaemon = true } }.apply {
            removeOnCancelPolicy = true
            scheduleWithFixedDelay({ synchronized(this@EmbeddedEngine) {
                val scope = observations
                if (scope != null && enabled && !stopping.get() && !failed.get()) {
                    try { refresh(scope) } catch (_: Exception) { controlLost() }
                }
            } }, 250, 1000, TimeUnit.MILLISECONDS)
        }
    }
    private fun refresh(scope: EngineScope) {
        val facts = controlOrFail().command("GETINFO status/bootstrap-phase status/circuit-established net/listeners/socks")
        val bootstrap = facts.singleOrNull { it.startsWith("status/bootstrap-phase=") }?.substringAfter('=') ?: throw IllegalStateException("CONTROL_PROTOCOL")
        ControlEvents.parse("STATUS_CLIENT $bootstrap", scope, phase).forEach { fact ->
            if (fact.kind == SignalKind.PROGRESS) phase = fact.phase
            sink.post(fact)
        }
        signal(SignalKind.CONTROL_AUTHENTICATED, scope)
        val circuit = facts.singleOrNull { it.startsWith("status/circuit-established=") }?.substringAfter('=')
        check(circuit in setOf("0", "1")) { "CONTROL_PROTOCOL" }
        val expected = "net/listeners/socks=\"unix:${File(run, "socks").absolutePath}\""
        check(facts.singleOrNull { it.startsWith("net/listeners/socks=") } == expected) { "INVALID_ENDPOINT" }
        if (circuit == "1") signal(SignalKind.CIRCUIT_ESTABLISHED, scope)
        signal(SignalKind.READY, scope, endpoint = SocksEndpoint.UnixSocket(File(run, "socks").absolutePath))
    }
    private fun controlLost() {
        if (!stopping.get() && failed.compareAndSet(false, true)) signal(SignalKind.CONTROL_LOST, EngineScope(generation, 0))
    }
    private fun stop(scope: EngineScope) {
        stopping.set(true); observations = null; enabled = false
        poller?.shutdownNow(); poller = null
        try { control?.command("SIGNAL SHUTDOWN") } catch (_: Exception) { /* TERM fallback */ }
        control?.close(); control = null
        if (handle != 0L) {
            NativeTor.signal(handle, false)
            if (!exited.await(2, TimeUnit.SECONDS)) { NativeTor.signal(handle, true); check(exited.await(500, TimeUnit.MILLISECONDS)) { "STOP_TIMEOUT" } }
            watcher?.join(500); check(watcher?.isAlive != true) { "STOP_TIMEOUT" }
            NativeTor.release(handle); handle = 0
        }
        for (name in listOf("socks", "control", "cookie")) {
            val file = File(run, name); check(!file.exists() || file.delete()) { "STOP_TIMEOUT" }
        }
        signal(SignalKind.STOPPED, scope)
    }
}
