#!/usr/bin/env node
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { phaseCheck, readOwnedRoles } from './guard-gha-env-roles-plan.mjs';
import { buildManifest, compareManifests } from './terraform-plan-manifest.mjs';
import { scopeMetadata, checkTargets, ensure } from './lib/gha-env-roles-saved-plan.mjs';
import { main as anchorCheck } from './gha-env-roles-anchor.mjs';

const [command] = process.argv.slice(2);
try {
  const phase = process.env.GHA_ENV_ROLES_PHASE;
  const scoped = scopeMetadata({ phase, disarm: process.env.DISARM_GHA_ENV_ROLES, retryOfRunId: process.env.RETRY_OF_RUN_ID ?? '' });
  mkdirSync('tmp/saved-plan-guards', { recursive: true });
  if (command === 'receipt') {
    ensure(/^[0-9a-f]{64}$/.test(process.env.APPROVED_MANIFEST_SHA256 ?? ''), 'approved_manifest_sha256 required');
    writeFileSync('tmp/saved-plan-guards/consumer.json', `${JSON.stringify({ ...scoped, run_id: process.env.GITHUB_RUN_ID, run_attempt: process.env.GITHUB_RUN_ATTEMPT,
      saved_plan_run_id: process.env.SAVED_PLAN_RUN_ID, approved_manifest_sha256: process.env.APPROVED_MANIFEST_SHA256 }, null, 2)}\n`);
  } else {
    ensure(['produce', 'compare'].includes(command), 'expected produce, compare or receipt');
    const dir = command === 'produce' ? 'tmp' : 'tmp/saved-plan';
    const binary = join(dir, 'tfplan-dev');
    const plan = JSON.parse(readFileSync(join(dir, 'tfplan-dev.json'), 'utf8'));
    const targets = readFileSync('tmp/gha-env-roles-targets.txt', 'utf8').trim().split(/\r?\n/);
    checkTargets(targets, { phase });
    let anchor;
    if (scoped.retry_of_run_id) {
      await anchorCheck(['--run-id', scoped.retry_of_run_id, '--phase', phase, '--role-specs-sha256', scoped.role_specs_sha256, '--out', 'tmp/gha-env-roles-anchor.json']);
      anchor = JSON.parse(readFileSync('tmp/gha-env-roles-anchor.json', 'utf8'));
    }
    const report = phaseCheck({ plan, env: 'dev', owned: readOwnedRoles({ env: 'dev' }), phase, targets, anchor });
    const state = JSON.parse(execFileSync('unzip', ['-p', binary, 'tfstate'], { encoding: 'utf8', timeout: 30000, maxBuffer: 128 * 1024 * 1024 }));
    const manifest = { ...buildManifest(plan, state, { targets }), gha_env_roles: report.gha_env_roles };
    if (command === 'compare') compareManifests(JSON.parse(readFileSync('tmp/saved-plan/manifest.json', 'utf8')), manifest);
    else writeFileSync('tmp/gha-env-roles-manifest.json', `${JSON.stringify(manifest, null, 2)}\n`);
    writeFileSync('tmp/saved-plan-guards/gha-env-roles-phase.json', `${JSON.stringify(report, null, 2)}\n`);
  }
} catch (e) { process.stderr.write(`${e.message}\n`); process.exitCode = 1; }
EOF
