const probeEnv = { ACTIONS_ID_TOKEN_REQUEST_URL: 'https://token.actions.githubusercontent.com/example', ACTIONS_ID_TOKEN_REQUEST_TOKEN: 'request-secret' };
function oidcProbe(overrides = {}) {
  const claims = { sub: devSubject, aud: 'sts.amazonaws.com', repository: 'Equicom-Crypto/crpko-devops', exp: Math.floor(Date.now() / 1000) + 600, ...overrides };
  const token = `header.${Buffer.from(JSON.stringify(claims)).toString('base64url')}.signature`;
  return { env: probeEnv, fetchToken: async (url, options) => {
    assert.equal(url.searchParams.get('audience'), 'sts.amazonaws.com');
    assert.equal(options.headers.Authorization, 'Bearer request-secret');
    return { ok: true, json: async () => ({ value: token }) };
  }, execute: (command, args, options) => {
