  return f;
}
test('A1 proves inert trust, all Deny resources and timestamped AccessDenied for the job dev identity', async () => {
  const f = a1(), report = await checkLive(f.options);
  assert.equal(f.live.simulations, 1); assert.equal(report.negative_assume.result, 'AccessDenied');
  assert.ok(Date.parse(report.negative_assume.attempted_at));
  assert.doesNotMatch(JSON.stringify(report), /request-secret|header\.|signature/);
