  ['transport error', { execute: () => { throw new Error('timeout'); } }],
  ['missing OIDC environment', { env: {} }],
  ['failed OIDC fetch', { fetchToken: async () => ({ ok: false }) }],
  ['wrong sub', oidcProbe({ sub: 'repo:Equicom-Crypto/crpko-devops:ref:refs/heads/main-dev' })],
  ['wrong audience', oidcProbe({ aud: 'other' })],
  ['wrong repository', oidcProbe({ repository: 'other' })],
  ['expired token', oidcProbe({ exp: 1 })],
]) test(`A1 refuses ${label} as negative-assume proof`, async () => {
  const f = a1(); f.options.probe = roleArn => negativeAssume({ roleArn, ...oidcProbe(), ...options });
