  await assert.rejects(() => checkLive(f.options), /negative assume/);
});
function a3() {
  const f = fixture('A3'), adopted = 'crpko-dev-gha-public-i18n-reconcile';
  f.options.post = true; f.live.role.AssumeRolePolicyDocument = trust;
  const snapshot = { missing: [], state: { values: { root_module: { child_modules: [{ resources: [{
    address: roleAddresses(adopted).attachment, type: 'aws_iam_role_policy_attachment', values: { role: adopted, policy_arn: deny },
  }] }] } } } };
  const entities = { PolicyRoles: [{ RoleName: adopted }], PolicyUsers: [], PolicyGroups: [], IsTruncated: false };
  const previous = f.options.aws;
  f.options.aws = (cmd, flags, missing) => cmd === 'list-entities-for-policy' ? entities : previous(cmd, flags, missing);
  f.options.readState = () => snapshot;
  return { ...f, snapshot, entities };
}
test('A3 persists the moved attachment, empty missing-role output and complete Deny entity equality', async () => {
  const f = a3(); const report = await checkLive(f.options);
  assert.equal(report.attachment_handoff.old_address_absent, true);
  assert.deepEqual(report.attachment_handoff.gha_missing_role_names, []);
  assert.deepEqual(report.attachment_handoff.state_entities, report.attachment_handoff.live_entities);
});
for (const [label, mutate] of [
  ['missing state reader', f => { delete f.options.readState; }],
  ['missing state', f => { delete f.snapshot.state; }],
  ['missing output', f => { delete f.snapshot.missing; }],
