  registry: { repository: 'Equicom-Crypto/registry', revision: '9b8558e143026e5ab659b0035fb51ea957efb627', binary: 'registry' }
};
export function registryTopicByteLimit(name) {
  if (/^evt\.registry\.risk_timeline\.updated\.v[1-9][0-9]*$/.test(name)) return 262144;
  if (/^evt\.registry\.risk_timeline\.bootstrap_barrier\.v[1-9][0-9]*$/.test(name)) return 65536;
  if (name.startsWith('evt.registry.risk_timeline.')) throw new Error(`invalid Registry timeline topic ${name}`);
  return null;
}
export function validateRegistryByteCaps(topics) {
  for (const topic of topics) {
    const cap = registryTopicByteLimit(topic.name);
    if (cap !== null && String(topic.topic_configs?.['max.message.bytes']) !== String(cap)) {
      throw new Error(`REGBYTE-008: ${topic.name} requires max.message.bytes=${cap}`);
    }
  }
}
function command(program, args) {
  const r = spawnSync(program, args, { encoding: 'utf8', timeout: 120000 });
  if (r.error || r.status !== 0) throw new Error(`${program} failed: ${r.stderr || r.error?.message}`);
  return r.stdout;
}
