func RunPendingStatsLoop(ctx context.Context, interval time.Duration, publisher *Publisher) error {
 return runPendingStatsLoops(ctx, interval, publisher, observability.NewTicker)
}

func runPendingStatsLoops(ctx context.Context, interval time.Duration, p *Publisher, newTicker observability.TickerFactory) error {
 var wg sync.WaitGroup
 for _, family := range []struct {
  name string
  interval time.Duration
  read func(context.Context) (float64, error)
 }{
  {"vr.outbox.pending_count", interval, func(ctx context.Context) (float64, error) {
   value, err := p.store.PendingCount(ctx); return float64(value), err
  }},
  {"vr.outbox.oldest_pending_age_ms", 10*time.Second, func(ctx context.Context) (float64, error) {
   value, err := p.store.OldestPendingAgeMS(ctx, time.Now()); return float64(value), err
  }},
 } {
  wg.Add(1)
  go func() {
   defer wg.Done()
   runStatsReadLoop(ctx, family.name, family.interval, family.read, newTicker)
  }()
 }
 wg.Wait()
 return nil
}

// A read has one worker at most, even if a client ignores cancellation. Such
// a worker can never stall another family or commit a result after its deadline.
func runStatsReadLoop(ctx context.Context, name string, interval time.Duration, read func(context.Context) (float64, error), newTicker observability.TickerFactory) {
 ticker := newTicker(interval)
 defer ticker.Stop()
 type result struct { value float64; err error }
 var pending <-chan result
 var readCtx context.Context
 var cancel context.CancelFunc
 defer func() { if cancel != nil { cancel() } }()
 for {
  select {
  case <-ctx.Done(): return
  case <-ticker.C():
   if ctx.Err() != nil { return }
   if pending != nil { continue }
   readCtx, cancel = context.WithTimeout(ctx, interval/2)
   results := make(chan result, 1)
   pending = results
   go func(readCtx context.Context) {
    value, err := read(readCtx)
    results <- result{value, err}
   }(readCtx)
  case result := <-pending:
   err := result.err
   if err == nil { err = readCtx.Err() }
   cancel()
   pending = nil
   if ctx.Err() != nil { return }
   if err != nil {
    observability.Log().Warn(ctx, "kafka.outbox.pending_stats.failed", observability.ErrorField(err))
    continue
   }
   observability.Stats().Gauge(name, result.value)
   observability.RecordAutoscalingGauge(ctx, name, result.value)
  }
 }
}
