import (
 "context"
 "strconv"
 "sync"
 "time"
)

type WSAccount struct { VenueID, VenueAccountID string }
type wsConnectedSeries struct { venueID, accountPresent string }
var wsConnectedState = struct {
 sync.Mutex
 taskID string
 active bool
 accounts map[WSAccount]bool
}{accounts: map[WSAccount]bool{}}

// StartWSMetrics seeds only configured accounts, before stream workers start.
func StartWSMetrics(ctx context.Context, taskID string, accounts []WSAccount) <-chan struct{} {
 return startWSMetrics(ctx, taskID, accounts, NewTicker)
}
func startWSMetrics(ctx context.Context, taskID string, accounts []WSAccount, newTicker TickerFactory) <-chan struct{} {
 wsConnectedState.Lock()
 wsConnectedState.taskID, wsConnectedState.active = taskID, ctx.Err() == nil
 wsConnectedState.accounts = make(map[WSAccount]bool, len(accounts))
 for _, account := range accounts { wsConnectedState.accounts[account] = false }
 if wsConnectedState.active { emitAllWSLocked() }
 wsConnectedState.Unlock()
 done := make(chan struct{})
 go func() {
  defer close(done)
  ticker := newTicker(10*time.Second)
  defer ticker.Stop()
  defer func() { wsConnectedState.Lock(); wsConnectedState.active = false; wsConnectedState.Unlock() }()
  for {
   select {
   case <-ctx.Done(): return
   case <-ticker.C():
    wsConnectedState.Lock()
    if ctx.Err() == nil { emitAllWSLocked() }
    wsConnectedState.Unlock()
   }
  }
 }()
 return done
}

// SetWSConnected updates only configured state. Events and timer snapshots share
// the lock so an older snapshot cannot overwrite a newer connection event.
func SetWSConnected(ctx context.Context, connected bool) {
 fields := FieldsFromContext(ctx)
 account := WSAccount{VenueID: fields.VenueID, VenueAccountID: fields.VenueAccountID}
 wsConnectedState.Lock()
 defer wsConnectedState.Unlock()
 prior, configured := wsConnectedState.accounts[account]
 if !configured || !wsConnectedState.active || ctx.Err() != nil || prior == connected { return }
 wsConnectedState.accounts[account] = connected
 emitWSLocked(wsConnectedSeries{account.VenueID, strconv.FormatBool(account.VenueAccountID != "")})
}
func emitAllWSLocked() {
 seen := map[wsConnectedSeries]bool{}
 for account := range wsConnectedState.accounts {
  series := wsConnectedSeries{account.VenueID, strconv.FormatBool(account.VenueAccountID != "")}
  if !seen[series] { emitWSLocked(series); seen[series] = true }
 }
}
func emitWSLocked(series wsConnectedSeries) {
 value := 0.0
 for account, connected := range wsConnectedState.accounts {
  if account.VenueID == series.venueID && strconv.FormatBool(account.VenueAccountID != "") == series.accountPresent && connected { value = 1 }
 }
 Stats().Gauge("vr.venue.ws_connected", value, Tag("venue_id", series.venueID), Tag("venue_account_present", series.accountPresent), Tag("task_id", wsConnectedState.taskID))
}
